code.Main.addBidirectionalPath:
// 正向：卸载点 / crusher / dump → loadSite
PathSegment forwardSeg = new PathSegment(
    this,
    positiveFrom,
    positiveTo,
    positiveFrom,
    positiveTo,
    speedLimit
);
// 反向：loadSite → 卸载点 / crusher / dump
